package ai.neu205.one;
import ai.neu205.one.imports.*;import java.io.*;import java.security.*;import java.util.concurrent.atomic.AtomicBoolean;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class GgufReferenceValidatorTest {
 void u32(ByteArrayOutputStream o,long n){for(int i=0;i<4;i++)o.write((int)(n>>(8*i))&255);}void u64(ByteArrayOutputStream o,long n){u32(o,n);u32(o,n>>>32);}void text(ByteArrayOutputStream o,String s)throws Exception{byte[] b=s.getBytes("UTF-8");u64(o,b.length);o.write(b);}
 byte[] fixture(String architecture,boolean template)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();u32(o,0x46554747);u32(o,3);u64(o,1);u64(o,template?2:1);text(o,"general.architecture");u32(o,8);text(o,architecture);if(template){text(o,"tokenizer.chat_template");u32(o,8);text(o,"{{ messages }}");}text(o,"synthetic_fixture_only");u32(o,1);u64(o,1);u32(o,0);u64(o,0);while(o.size()%32!=0)o.write(0);o.write(new byte[32]);return o.toByteArray();}
 GgufReferenceValidator.Receipt receipt(byte[] bytes,String arch)throws Exception{StringBuilder sha=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))sha.append(String.format("%02x",b&255));return new GgufReferenceValidator.Receipt(new JSONObject().put("sha256",sha.toString()).put("bytes",bytes.length).put("architecture",arch));}
 @Test public void validSyntheticHeaderAndHashRetainsNoWeights()throws Exception{byte[] bytes=fixture("qwen3",true);var r=GgufReferenceValidator.verify(new ByteArrayInputStream(bytes),receipt(bytes,"qwen3"),new AtomicBoolean(),null);assertEquals(1,r.tensors);assertFalse(r.metadata().getBoolean("weight_copy_created"));assertFalse(r.metadata().getBoolean("companion_access_verified"));}
 @Test public void changedWeightByteRejected()throws Exception{byte[] bytes=fixture("qwen3",true);var expected=receipt(bytes,"qwen3");bytes[bytes.length-1]=1;try{GgufReferenceValidator.verify(new ByteArrayInputStream(bytes),expected,new AtomicBoolean(),null);fail();}catch(IOException correct){}}
 @Test public void architectureMismatchRejected()throws Exception{byte[] bytes=fixture("llama",true);try{GgufReferenceValidator.verify(new ByteArrayInputStream(bytes),receipt(bytes,"qwen3"),new AtomicBoolean(),null);fail();}catch(IOException correct){}}
 @Test public void missingTemplateRejected()throws Exception{byte[] bytes=fixture("qwen3",false);try{GgufReferenceValidator.verify(new ByteArrayInputStream(bytes),receipt(bytes,"qwen3"),new AtomicBoolean(),null);fail();}catch(IOException correct){}}
 @Test public void cancellationRejectedBeforeReference()throws Exception{byte[] bytes=fixture("qwen3",true);try{GgufReferenceValidator.verify(new ByteArrayInputStream(bytes),receipt(bytes,"qwen3"),new AtomicBoolean(true),null);fail();}catch(InterruptedIOException correct){}}
}
